-- October 2026 complaints imported from the Lviv review sheet (sheet 2), checked against the reporting sheet.
-- Re-running is safe: external_id is unique.
insert into complaints (location_id, channel, happened_on, text, topics, source, external_id)
select l.id, v.channel, v.d::date, v.text, v.topics::text[], 'sheet', v.ext
from (values
  ('Львів, Валова 13', 'Glovo', '2026-10-01', 'Лаваш розмʼякший та все розлетілося, також мʼясо підгоріле', '{"Розвалюється","М''ясо"}', 'sheet:2026-10:c93bf38a5a'),
  ('Львів, Валова 13', 'Google', '2026-10-10', 'Фрі чорна, ваняє старою олією ,так само ваняє і в самому закладі, чекали на 2 кебаба 20 хвилин на кебабі пригорівше волосся ,кебаб якийсь кислющий чи оцетовий нічо не розумію, соус як вода витікає всюди де тільки можна ,люди не витрачайте свій час і гроші підіть навпроти в кебаб на мангалі і не труїться старою олією і волоссям з кислими соусами в кебабі', '{"Чистота","Сторонній предмет","Довге очікування","Соус"}', 'sheet:2026-10:c738c06d56'),
  ('Львів, Кульпарківська', 'Google', '2026-10-02', 'Вітаю) Почну з персоналу :пані блондинка ,яка була готова приймати замовлення була не задоволена очікуванням поки ми оформляли додаток, покинула касу і вийшла до нас інший працівник,це було приблизно 11:20 люде не було та черги також.Замовлення подали швидко.Кебаб був проходоний , мʼясо засохше з вчора , оскільки всі грилі були чисті і мʼясо не смажилось.Так потрібно покупцям казати , що кебаб вчорашні .Кебабця для мене завжди смакота, але у Вікторії гарденс все на впаки .Мені шкода .', '{"Персонал","М''ясо"}', 'sheet:2026-10:6ff9d80b91'),
  ('Львів, Кульпарківська', 'Google', '2026-10-03', 'Брала курячий кебаб розчарування. Цибуля дуже перебиває смак, начинка дивно розділена: окремо курка, окремо все інше. У результаті кожен укус або м’ясо, або овочі. Ще й попався маленький чорний волосок. За таку ціну є набагато смачніші кебаби.', '{"Овочі / капуста","Сторонній предмет","Розмір і ціна"}', 'sheet:2026-10:01f869dd58'),
  ('Львів, Кульпарківська', 'Google', '2026-10-06', 'Надто багато соусу', '{"Соус"}', 'sheet:2026-10:7ee71f0123'),
  ('Львів, Кульпарківська', 'Google', '2026-10-07', 'Чекали на своє замовлення більше ніж пів години, після чого підійшли до каси де сказали що просто забули видрукувати замовлення. Вирішення ситуації немає, замість того щоб визнати свою халатність та виконати замовлення поза чергою сказали ще очікувати або повернення коштів, звісно що повернули кошти, це був перший досвід з цим закладом та бажання повертатись немає, жахливий сервіс', '{"Довге очікування","Персонал"}', 'sheet:2026-10:4a9618c2a7'),
  ('Львів, Кульпарківська', 'Google', '2026-10-13', 'Крім того шо чекав свій кебаб хвилин 25, принесли просто розвалений, просто накидали шо попало під руку, люблю їсти в їх закладах але не тут', '{"Довге очікування","Розвалюється"}', 'sheet:2026-10:0be2b3a1a4'),
  ('Львів, Кульпарківська', 'Google', '2026-10-14', 'Брав сьогодні кебаб середньої гостроти, нажаль халапеньо так і не було, коштує додатково 30грн. Сам кебаб був доволі смачним але весь розлізся і нижня частина залишилася в кульочку бо незручно було їсти.', '{"Забули додаток","Розвалюється"}', 'sheet:2026-10:8288f85172'),
  ('Львів, Кульпарківська', 'Google', '2026-10-17', 'Позначають онлайн замовлення як виконані , проте їх не видають , і кажуть ще готується', '{"Персонал"}', 'sheet:2026-10:7893709c6c'),
  ('Львів, Чорновола 16', 'Google', '2026-10-06', 'Кебабцю замовляю з моменту відкриття і є з чим порівняти. Смак, розмір, нажаль змінюються не в кращу сторону((
Розмір махі змінився майже на половину, та став більш схожий до міні. Різниця зараз мінімальна між ними та розчаровує. Соус зовсім вже без того насиченого смаку. Картопельку замовивши з 150грам отримала зкомкану жменьку ніби ліпили сніжну кульку(( по вигляду щоб там 100гр хоть було. Розчарована. Розривається з однієї сторони а сухий з іншої( мяско не мега свіже і після важкий осад в шлунку(( нажаль', '{"Розмір і ціна","Соус","М''ясо"}', 'sheet:2026-10:64643dc893'),
  ('Львів, Чорновола 16', 'Google', '2026-10-07', 'В кебабі знайшов харчову плівку, якщо в лікарню поляжу будете мати проблеми', '{"Сторонній предмет"}', 'sheet:2026-10:a785d46f73'),
  ('Львів, Чорновола 16', 'Instagram', '2026-10-10', 'не поклали соус у кебокси', '{"Соус","Забули додаток"}', 'sheet:2026-10:123b3cc747'),
  ('Львів, Чорновола 16', 'Google', '2026-10-13', 'Замовляю кебаб із халапеньйо вже п’ятий раз, і його знову немає! Для чого пропонувати додаткові інгредієнти, якщо ви їх постійно забуваєте покласти? Будь ласка, почніть перевіряти замовлення. Це вже не випадковість, а систематична проблема із сервісом.', '{"Забули додаток"}', 'sheet:2026-10:c398d1beda'),
  ('Львів, Хуторівка', 'Google', '2026-10-03', 'Найгірший кебаб, який я їв у «Кебабці», — на нижньому Шуварі! Дуже мало м’яса, майже немає соусу — в основному одна капуста. Залишився дуже розчарований.', '{"Розмір і ціна","Соус","Овочі / капуста"}', 'sheet:2026-10:53aaff3ed8'),
  ('Львів, Княгині Ольги 100л', 'Google', '2026-10-06', 'Придбав 2 кебаба у боксі ( мікс, курка), капуста настільки гірка що довелося все викинути.', '{"Овочі / капуста"}', 'sheet:2026-10:ebe3b54da8'),
  ('Львів, Княгині Ольги 100л', 'Google', '2026-10-17', 'Незнаю що сталося , але шаурма стала дуже суха і несмачна, плюс касир не уточнила за картоплю фрі, куди їі давати', '{"М''ясо","Персонал"}', 'sheet:2026-10:8b2736d0ed'),
  ('Львів, Шевченка 309', 'Google', '2026-10-06', 'Це треш, кебабця дивіться як у вас роблять кебаб 😳 (фото з кебабом, що розлетівся)', '{"Розвалюється"}', 'sheet:2026-10:cc9f333ac6'),
  ('Львів, Шевченка 309', 'Оцінки в додатку', '2026-10-12', 'Було смачно, мені. Але є нюанси.
Замовлення з 3 міксів, вийшло одним міксом і двома курками, на що я не маю претензій, мені компенсували готівкою різницю, а я як працівник схожого закладу, розумію.
Проблема ось в чому: замовив Халапеньо до двох кебабів з трьох. В результаті всі були гострі, в чому переконався особисто. А третій особі не можна гостре... 
Плюсом, лаваші розмокли, поки я ніс їх додому. А я живу через дорогу від закладу...
Я був згоден з тим, що м''ясо закінчилось під вечір, але я заплатив майже 1к, і хочу хоча б отримати гарантію смаку і вражень. Взяв би в своєму закладі перед закінченням зміни, стан був би той самий, а ціна в півтора рази менша.
Я не хотів оперувати до ціни, але це факт, тим більш двоє з трьох людей не задоволені повністю, а я тепер маю не розслаблення після роботи, а нерви, бо їм не сподобалось.
Нажаль більше не буду у вас купувати. Дякую за вечерю, і сподіваюсь в інших все буде ок', '{"Забули додаток","Розвалюється","М''ясо"}', 'sheet:2026-10:9378090a52'),
  ('Львів, Шевченка 309', 'Bolt', '2026-10-15', 'Обовʼязково треба робити вибір 2х додатків до стави. Без цього замовлення не можливо здійснити', '{"Додаток / бонуси"}', 'sheet:2026-10:e227b388db'),
  ('Львів, Широка', 'Bolt', '2026-10-01', 'Розвалюється кебаб при споживанні', '{"Розвалюється"}', 'sheet:2026-10:9b535edcd4'),
  ('Львів, Широка', 'Google', '2026-10-18', 'Відмовилися приймати замовлення, бо скоро відключення світла. Який рік війни, а заклад не забезпечений резервним живленням. Мова саме про цей заклад.', '{"Персонал"}', 'sheet:2026-10:2dc385ecba'),
  ('Львів, Гетьмана Мазепи 1Б', 'Glovo', '2026-10-01', 'Кебаби не підписані, напій до замовлення не додали, + в один з кебабів потрапила мушка', '{"Забули додаток","Сторонній предмет"}', 'sheet:2026-10:1f812912f2'),
  ('Львів, Гетьмана Мазепи 1Б', 'Оцінки в додатку', '2026-10-04', 'В ЦЕЗАРІ МАЙЖЕ НЕ БУЛО СОУСУ ХАЛАПЕНЬО НЕ РІВНОМІРНО РОЗПОДІЛЕНЕ', '{"Соус"}', 'sheet:2026-10:42c4826efb'),
  ('Львів, Гетьмана Мазепи 1Б', 'Google', '2026-10-18', 'Начинки критично мало, м’яса майже не знайти, лаваш розвалюється, а картопля фрі пересмажена й виглядає жахливо. За такі гроші — відверте розчарування. Економлять на всьому, крім ціни. Не рекомендую!', '{"Розмір і ціна","Розвалюється"}', 'sheet:2026-10:bfea9fe431')
) as v(loc, channel, d, text, topics, ext)
join locations l on l.name = v.loc
on conflict (external_id) do nothing;

-- Google at the start of October 2026, from the reporting sheet: review count and start rating.
insert into google_monthly (location_id, month, total, start_rating)
select l.id, '2026-10-01', v.total, v.r
from (values
  ('Львів, Валова 13', null::int, 3.9),
  ('Львів, Героїв УПА 73', 173, 4.1),
  ('Львів, Чорновола 16', 107, 4.6),
  ('Львів, Шевченка 309', 189, 4.7),
  ('Львів, Гетьмана Мазепи 1Б', 240, 3.9),
  ('Львів, Крива Липа 8', 281, 3.9),
  ('Львів, Княгині Ольги 100л', 124, 4.0),
  ('Львів, Червоної Калини 109', 142, 4.0),
  ('Львів, Чернівецька', 105, 4.6),
  ('Львів, Хуторівка', 34, 3.7),
  ('Львів, Під дубом', 79, 4.1),
  ('Львів, Кульпарківська', 127, 4.0),
  ('Львів, Широка', 77, 3.9),
  ('Львів, Сокільники', 87, 4.3),
  ('Львів, Шевченка 60', 127, 4.8),
  ('Дрогобич', 68, 4.2),
  ('Стрий', 80, 4.1),
  ('Пустомити', 69, 4.1),
  ('Поляниця', 82, 4.1),
  ('Ужгород', 64, 4.4),
  ('Буковель', 22, 4.6),
  ('Яремче', 24, 4.0),
  ('Чернівці, Небесної Сотні', 72, 4.3),
  ('Івано-Франківськ, Бельведерська 28', 113, 4.0),
  ('Луцьк, Крилова 6', 61, 3.8),
  ('Шептицький', 49, 3.8),
  ('Тернопіль, бульвар Шевченка', 149, 4.4)
) as v(loc, total, r)
join locations l on l.name = v.loc
on conflict (location_id, month) do update set total = coalesce(excluded.total, google_monthly.total), start_rating = excluded.start_rating;
